// فصل 13 از کتاب — تبدیل‌شده از نسخهٔ HTML؛ ویرایش دستی لازم نیست.
// Chapter 13 of the book — converted from the HTML edition; generated file.

export const n = 13;
export const num = "13";
export const title = "کار موازی — stash، worktree و sparse-checkout";
export const label = "فصل ۱۳ · stash و worktree";
export const part = 1;
export const html = "<p class=\"lead\">اگر وسط یک فیچر ناقص باگ تولید آمد، دو راه تمیز داری: تغییرات را موقتاً کنار بگذار (stash) یا همان مخزن را در پوشهٔ دوم روی شاخهٔ دیگر باز کن (worktree). کامیت الکی روی فیچر نزن.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>stash را با پیام نام‌گذاری کنی و درست برگردانی</li>\n<li>worktree را برای کار همزمان روی دو شاخه راه بیندازی</li>\n<li>sparse-checkout را در monorepo بفهمی</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">📥 stash — قفسهٔ موقت</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">stash تمیز</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>stash<span style=\"color: #F8F8F2\"> </span>push<span style=\"color: #F8F8F2\"> </span>-u<span style=\"color: #F8F8F2\"> </span>-m<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;wip: jwt tests&quot;</span>\ngit<span style=\"color: #F8F8F2\"> </span>stash<span style=\"color: #F8F8F2\"> </span>list\ngit<span style=\"color: #F8F8F2\"> </span>stash<span style=\"color: #F8F8F2\"> </span>show<span style=\"color: #F8F8F2\"> </span>-p<span style=\"color: #F8F8F2\"> </span>stash@<span style=\"color: #FF4689\">{</span><span style=\"color: #AE81FF\">0</span><span style=\"color: #FF4689\">}</span>\ngit<span style=\"color: #F8F8F2\"> </span>stash<span style=\"color: #F8F8F2\"> </span>pop<span style=\"color: #F8F8F2\">                  </span><span style=\"color: #959077\"># اعمال + حذف</span>\ngit<span style=\"color: #F8F8F2\"> </span>stash<span style=\"color: #F8F8F2\"> </span>apply<span style=\"color: #F8F8F2\"> </span>stash@<span style=\"color: #FF4689\">{</span><span style=\"color: #AE81FF\">1</span><span style=\"color: #FF4689\">}</span><span style=\"color: #F8F8F2\">      </span><span style=\"color: #959077\"># اعمال، نگه داشتن</span>\ngit<span style=\"color: #F8F8F2\"> </span>stash<span style=\"color: #F8F8F2\"> </span>drop<span style=\"color: #F8F8F2\"> </span>stash@<span style=\"color: #FF4689\">{</span><span style=\"color: #AE81FF\">1</span><span style=\"color: #FF4689\">}</span>\ngit<span style=\"color: #F8F8F2\"> </span>stash<span style=\"color: #F8F8F2\"> </span>branch<span style=\"color: #F8F8F2\"> </span>rescue<span style=\"color: #F8F8F2\"> </span>stash@<span style=\"color: #FF4689\">{</span><span style=\"color: #AE81FF\">0</span><span style=\"color: #FF4689\">}</span>\n</pre></div>\n<p class=\"keep-next\"><code>-u</code> فایل Untracked را هم می‌گیرد. بدون آن <code>notes.txt</code> جدید جا می‌ماند و <code>switch</code> ممکن است شکست بخورد.</p>\n<div class=\"cols\">\n<div class=\"col\"><div class=\"col-title\">🖥️ VS Code Git</div>\n<p>Source Control → <code>...</code> → <strong>Stash</strong></p>\n<ul>\n<li><em>Stash (Include Untracked)</em></li>\n<li><em>Stash All</em></li>\n<li><em>Pop Latest Stash</em> / <em>Apply Latest Stash</em>\nلیست stashها در همان منو دیده می‌شود.</li>\n</ul>\n</div>\n<div class=\"col\"><div class=\"col-title\">⌨️ Terminal</div>\n<p><code>git stash push -u -m &quot;wip&quot;</code>\n<code>git stash pop</code>\n<code>git stash apply stash@{1}</code></p>\n</div>\n</div>\n<div class=\"shot\">\n<img src=\"/book/figures/vscode-stash-sync.png\" alt=\"منوی Stash و Sync در VS Code\"/>\n<p class=\"figcap\">شکل ۱۳ — منوی ··· در Source Control: Fetch، Pull (Rebase)، Stash، Undo Last Commit و Sync در نوار وضعیت.</p>\n</div>\n<div class=\"callout callout-warn\"><div class=\"callout-title\">stash pop تعارض</div>\n<p>اگر تعارض آمد، stash حذف نمی‌شود (<code>pop</code> شکست می‌خورد). حل کن، بعد <code>drop</code>. <code>apply</code> در این مواقع شفاف‌تر است.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🌲 worktree — چند checkout واقعی</span></span></h2>\n<p class=\"keep-next\">worktree یعنی یک پوشهٔ دوم از همان پروژه، روی شاخه‌ای دیگر. فایل‌ها جدایند، اما تاریخچه (پوشهٔ <code>.git</code>) مشترک است — پس کامیت در پوشهٔ دوم در همان مخزن ثبت می‌شود.</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">هات‌فیکس کنار فیچر</span></div><pre><span style=\"color: #959077\"># از مخزن اصلی</span>\ngit<span style=\"color: #F8F8F2\"> </span>worktree<span style=\"color: #F8F8F2\"> </span>add<span style=\"color: #F8F8F2\"> </span>../app-hotfix<span style=\"color: #F8F8F2\"> </span>-b<span style=\"color: #F8F8F2\"> </span>hotfix/500<span style=\"color: #F8F8F2\"> </span>main\ncode<span style=\"color: #F8F8F2\"> </span>-n<span style=\"color: #F8F8F2\"> </span>../app-hotfix\n<span style=\"color: #959077\"># بعد از اتمام</span>\ngit<span style=\"color: #F8F8F2\"> </span>worktree<span style=\"color: #F8F8F2\"> </span>remove<span style=\"color: #F8F8F2\"> </span>../app-hotfix\ngit<span style=\"color: #F8F8F2\"> </span>worktree<span style=\"color: #F8F8F2\"> </span>list\n</pre></div>\n<p class=\"keep-next\">قواعد:</p>\n<ul>\n<li>یک شاخه در دو worktree همزمان checkout نمی‌شود</li>\n<li>برای PR موازی و عامل‌های AI (فصل ۳۲) ایده‌آل است</li>\n<li><code>remove</code> قبل از پاک کردن پوشه</li>\n</ul>\n<p>VS Code هر worktree را به‌صورت پوشهٔ جدا باز می‌کند — Source Control مستقل، تاریخچه مشترک.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">📦 sparse-checkout و partial clone</span></span></h2>\n<p class=\"keep-next\">در monorepo که ۱۰ گیگ است، کل درخت را لازم نداری.</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">فقط پوشهٔ خودت</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>clone<span style=\"color: #F8F8F2\"> </span>--filter<span style=\"color: #FF4689\">=</span>blob:none<span style=\"color: #F8F8F2\"> </span>--sparse<span style=\"color: #F8F8F2\"> </span>git@github.com:org/mono.git\n<span style=\"color: #F8F8F2\">cd </span>mono\ngit<span style=\"color: #F8F8F2\"> </span>sparse-checkout<span style=\"color: #F8F8F2\"> set </span>apps/web<span style=\"color: #F8F8F2\"> </span>packages/ui\n</pre></div>\n<p><code>--filter=blob:none</code> (partial clone) blobها را تنبلانه می‌گیرد. GitHub این را پشتیبانی می‌کند. Scalar (ابزار مایکروسافت) همین ایده را برای ویندوز بزرگ خودکار می‌کند — فصل ۳۱.</p>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Junior — stash کجا ذخیره می‌شود؟</strong> refهای <code>refs/stash</code> و کامیت‌های merge-مانند در objects.</p>\n<p><strong>Mid — کی worktree، کی stash؟</strong> stash برای دقیقه؛ worktree برای ساعت و روز و PR موازی.</p>\n<p><strong>Senior — چرا شاخه در دو worktree ممنوع است؟</strong> چون هر دو HEAD و Index می‌خواهند همان ref را حرکت دهند — مسابقه.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ چک‌لیست فهم</span></span></h2>\n<div class=\"keep-block\"><div class=\"checklist\">\n<ul>\n<li>stash با پیام می‌سازی نه <code>stash@{7}</code> بی‌نام</li>\n<li>یک worktree واقعی باز کرده‌ای</li>\n<li>فرق partial clone و sparse را بلدی</li>\n</ul>\n</div><p><strong>فصل بعد:</strong> remote — origin، fetch، pull، push.</p></div>";
export default { n, num, title, label, part, html };
